import{_ as r,l as o,o as e,c as s,v as t,p as n,x as l,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"掩模背面颗粒","description":"","frontmatter":{"title":"掩模背面颗粒","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/reticle-backside-particles.md","filePath":"litho/reticle-backside-particles.md","lastUpdated":1789023840000}'),h={name:"litho/reticle-backside-particles.md"};function E(_,a,A,m,u,f){const i=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="掩模背面颗粒" tabindex="-1">掩模背面颗粒 <a class="header-anchor" href="#掩模背面颗粒" aria-label="Permalink to &quot;掩模背面颗粒&quot;">​</a></h1><div class="epigraph"><p>正面颗粒挡多层、投阴影；背面颗粒夹在吸盘与基板之间，把版顶出一个局部凸包，全场焦面和放大率跟着走。</p><footer>—— 对照 EUV 掩模背面颗粒与静电吸盘的公开讨论；ASML 洁净搬运</footer></div><p><a href="/litho/euv-reticle-chuck">上一课</a>把夹持力写成静电压力。缺口是压力对间隙极其敏感：一颗微米级颗粒就能局部撑开吸盘，掩模变成「带鼓包的反射镜」。本课钉背面颗粒。光源与光学课序收到这里；下一单元从<a href="/litho/low-n-absorber">低 n 吸收体</a>起，改看正面图形材料。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>吸盘课假设背面贴合。真实背面有搬运划伤、镀膜颗粒和库内沉降。真空中没有气体阻尼，颗粒一旦夹入就不易被气流吹走。凸包高度按颗粒尺寸和基板刚度分配，到正面可以是纳米到数十纳米的面形——正好落在焦深和套刻预算里。它不像正面缺陷那样在硅片上印出硬点子，而像一层随夹持电压变的场曲，排查时容易被当成工件台或镜头热。</p><p>缺口是把背面当成成像面的一部分，而不是洁净室附录。pellicle 保护正面，不保护背面。无 pellicle 运行时两边都裸，风险叠加，后课再写。</p><p><span class="marginnote">DUV 透射版的背面颗粒主要挡光或离焦；EUV 背面颗粒的第一效应是机械面形，因为光不从背面穿过来。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>防：背面洁净规格、专用盒、机械手接触点、吸盘表面本身的产尘控制。检：上机前背面检测，吸盘上的真空/静电贴合传感器看局部间隙。纠：吹扫有限，通常要下机清洗或报废；反复夹持可能把颗粒压进基板，变成永久坑。</p><p>与套刻：鼓包引起的局部放大率和旋转像一层「伪 overlay」，层间若两次夹持颗粒不同，套刻飘。因此背面事件要进 SPC，不能只看正面缺陷图。</p><h3 id="检测必须在夹持态或等价载荷下" tabindex="-1">检测必须在夹持态或等价载荷下 <a class="header-anchor" href="#检测必须在夹持态或等价载荷下" aria-label="Permalink to &quot;检测必须在夹持态或等价载荷下&quot;">​</a></h3><p>未夹持的背面光学检查能看见颗粒，估不准凸包高度——刚度、电压和颗粒硬度一起决定。上机贴合传感器或夹持后面形图才能把事件判到焦深预算里。下机清洗若把颗粒压进基板，检测会从「颗粒」变成「坑」，更难清。接触点设计比事后吹扫有效。</p>',12)),(e(),n(p,null,{default:l(()=>[d(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E8%83%8C%E9%9D%A2%E9%A2%97%E7%B2%92%22%5D%20--%3E%20GAP%5B%22%E5%B1%80%E9%83%A8%E6%92%91%E5%BC%80%20ESC%22%5D%0A%20%20GAP%20--%3E%20BUMP%5B%22%E5%9F%BA%E6%9D%BF%E5%87%B8%E5%8C%85%22%5D%0A%20%20BUMP%20--%3E%20FOC%5B%22%E5%B1%80%E9%83%A8%E7%84%A6%E9%9D%A2%22%5D%0A%20%20BUMP%20--%3E%20MAG%5B%22%E5%B1%80%E9%83%A8%E6%94%BE%E5%A4%A7%E7%8E%87%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>接触力学：硬颗粒当支点，静电压力试图把板压回去，弯曲能量与颗粒高度平衡，凸包半径可达毫米–厘米，高度衰减但仍在纳米。扫描时惯性可能让颗粒移位，指纹变成时变。氢和 EUV 不直接「烧掉」这颗颗粒，除非它在等离子体里被刻蚀——背面通常不在强 EUV 足迹下。</p><p><span class="marginnote">不要把背面凸包修进 OPC。它是夹持态缺陷，换一次吸盘或清一次背面就会变。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写吸收体 n、k，那是下一单元第一课。不重写掩模厂背面抛光工艺——后一课程「掩模制造」会从数据准备另起，本课只把扫描机侧的背面风险钉死。正面 pellicle 不降低本课的夹持力学。出处：ASML 掩模搬运与吸盘；EUV 背面颗粒公开讨论；吸盘课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>背面颗粒通过 ESC 变成版面凸包，进入焦面与套刻，而不是印硬缺陷。</li><li>pellicle 不管背面；检测和接触点设计是主防线。</li><li>光源与光学课序结束；下一单元从正面吸收体材料接着。</li><li>出处：ASML；EUV reticle backside 公开讨论。</li></ul>',7))])}const B=r(h,[["render",E]]);export{b as __pageData,B as default};
